entries[247719] = { ["name"] = "Multicraft Matrix", ["text"] = "Binds when picked up\nUse: Combine 5 Multicraft Matrices to create a Multicraft Manifold.\nFinishing Crafting Reagent\n\nWhen crafting: A dimensional oddity that might result in additional crafting output.\n|NGain 90 Multicraft for this craft.\nUsable with: Midnight recipes that are eligible for Multicraft.\nSell Price:" }
entries[247720] = { ["name"] = "The Headless Horseman's Chilling Charger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Through the air you will fly, on your foes you descend, this charger will carry you to deliver their end.\"\nTrading Post" }
entries[247721] = { ["name"] = "The Headless Horseman's Ghoulish Charger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Tricks have been played, your enemies beaten, this ghoulish charger awaits a treat, friend.\"\nDrop:\nLoot-Filled Pumpkin\nHoliday:\nHallow's End" }
entries[247722] = { ["name"] = "The Headless Horseman's Burning Charger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The fires blaze on, in the steed's heart and soul, now take to the sky as a sight to behold.\"\nTrading Post" }
entries[247723] = { ["name"] = "The Headless Horseman's Hallowed Charger", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Your future's unknown, with ghosts in your past. With your steed at your side, how long can you last?\"\nTrading Post" }
