entries[247791] = { ["name"] = "Adorned Northeron Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The elder gryphon riders and high shamans of the Northeron Wildhammer often adorned their gryphons in ornate, feather-clad pieces, indicating their rank and status.\"\nTrading Post" }
entries[247792] = { ["name"] = "High Shaman's Aerie Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The ancient Wildhammer shamans who first encountered gryphons believed them to be elemental spirits in mortal form. This encounter would forever imprint on the Wildhammer clan for generations to come.\"\nTrading Post" }
entries[247793] = { ["name"] = "Cinder-Plumed Highland Gryphon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"According to Wildhammer legend, the orange plumage found on gryphons is believed to be a hereditary trait passed down from their elemental ancestry.\"\nTrading Post" }
entries[247794] = { ["name"] = "Emberwing Sky Guide", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"From the foothills of Khaz Modan, we followed its ember-lit wings--a northbound torch across the dark summer sky.\" - The Pilgrimage of the First Wildsage\nTrading Post" }
entries[247795] = { ["name"] = "Ornery Breezestrider", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Ornery Breezestrider.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"This talbuk is a stubborn, obstinate mount, even after getting to know its rider. Riders beware.\"\nTrading Post" }
entries[247808] = { ["name"] = "Bronze Simulacrum", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\nRequires level 10 to 90 ( 90)\n\"An artifact forgery flawlessly fabricated by Momentus. Now that you have reclaimed this copy, you can scrap it for the bronze it's made of.\"" }
entries[247811] = { ["name"] = "Oil of Heartwood", ["text"] = "Binds when picked up\nCrafting Reagent\n\"An alchemical reagent used for neutralizing the effects of potions and flasks. Can be purchased from Alchemy suppliers throughout Midnight zones.\"\nSell Price:" }
