entries[248088] = { ["name"] = "Jade, Bright Foreseer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The presence of this majestic Pandaren rabbit spirit brings joy and happiness and is heralded as a wonderful omen. Legend says that in its eyes, you can glimpse the greatest happiness of your life, even if it is yet to come.\"\nIn-Game Shop" }
entries[248089] = { ["name"] = "Tangled Dreamweaver", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The last of the sleepers are finally awakening, bringing the dreams of the dragons back to the lands.\"\nPromotion:\nDragonflight Heroic Edition" }
entries[248090] = { ["name"] = "Viridian Phase-Hunter", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Hailing from a species already adept at natural camouflage, the otherworldly energies that transformed Draenor into Outland gave these creatures the ability to shift through space.\"\nPromotion" }
