entries[248131] = { ["name"] = "Key to the Arcantina", ["text"] = "Quest Item\nUse: Teleports the user to, or back from, the Arcantina. (1 Min, 30 Sec Cooldown)\n\"Teleports the user to, or back from, the Arcantina's pocket dimension.\"" }
entries[248132] = { ["name"] = "Kinetic Ankle Primers", ["text"] = "Optional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Prime your boots for engagement, launching you into the air and knocking up enemies on impact.\n\nCan only be used outdoors.\nUsable with: Midnight Engineering Boots \"Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[248133] = { ["name"] = "Kinetic Ankle Primers", ["text"] = "Optional Crafting Reagent\n+5 Recipe Difficulty\nProvides the following property: Prime your boots for engagement, launching you into the air and knocking up enemies on impact.\n\nCan only be used outdoors.\nUsable with: Midnight Engineering Boots \"Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[248135] = { ["name"] = "B1P, Scorcher of Souls", ["text"] = "Optional Crafting Reagent\n+15 Recipe Difficulty\nProvides the following property: Summons Bip, Scorcher of Souls to spray soul sparks on your enemies dealing ( 846 * (12)) Fire damage in a cone in front of you for 6 sec.\nUsable with: Midnight Engineering Crafted Equipment \"Summons Bip, Soul Scorcher. Created by players with the Engineering skill. Can be bought and sold on the Auction House.\"\nSell Price:" }
entries[248136] = { ["name"] = "M3DDY, Travel-Sized", ["text"] = "Optional Crafting Reagent\n\nProvides the following property:\n\nA pocket-sized version of your buddy Meddy that will revive you upon your untimely demise while outdoors.\nUsable with: Midnight recipes for most unembellished equipment.\nSell Price:" }
entries[248137] = { ["name"] = "M3DDY", ["text"] = "Use: Upon your untimely demise, summon Meddy to... medicalize you and your raid back to life!\n\nDoes not work on players whose spirits have been released and are above level 90.\nSell Price:" }
entries[248138] = { ["name"] = "Curious Red Button", ["text"] = "Use: Deploy a particularly curious device.\n\nLasts for 10 min. Must be deployed prior to combat. Only usable outdoors. (10 Min Cooldown)\nSell Price:" }
