entries[248140] = { ["name"] = "Bronze Simulacrum", ["text"] = "Binds when picked up\nRequires level 10 to 90 ( 90)\n\"An artifact forgery flawlessly fabricated by Momentus. Now that you have reclaimed this copy, you can scrap it for the bronze it's made of.\"" }
