entries[248409] = { ["name"] = "W-47CH D0G", ["text"] = "Use: Deploy a W-47CH D0G unit that will calm the nerves of nearby party members, halting the expiration of Thalassian Flasks, Phials, and Well Fed effects.\n\nThe pylon is extremely fragile and will detonate in the presence of violence.\nSell Price:" }
entries[248410] = { ["name"] = "Technomancer's Gift", ["text"] = "Binds when picked up\nUse: Add a socket to a War Within Season 3 item that does not already have one. Can be used on Helms, Bracers, or Belts. Cannot be used on PvP equipment." }
entries[248485] = { ["name"] = "Wormhole Generator: Quel'Thalas", ["text"] = "Toy\nUse: Open a wormhole that allows the user to quickly travel to a random Midnight location. (30 Min Cooldown)\nRequires Midnight Engineering (1)\nSell Price:" }
entries[248486] = { ["name"] = "Emergency Soul Link", ["text"] = "Use: Convince a dead ally that being alive is much more fun by catalyzing your whimsy, restoring them to life with 35% health and 10% mana. This always succeeds because it's objective truth.\n\nCastable in combat. Item quality affects cast time. Cannot be used by players higher than level 90. (10 Min Cooldown)\nSell Price:" }
