entries[249339] = { ["name"] = "Gloom-Spattered Dreadscale", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 13 Critical Strike\nUse: Unleash a burst of hungering Gloom, dealing 3489 Shadow damage split between nearby enemies and absorbing up to 50% of incoming damage until an equal amount of damage has been prevented.\n\nDamage increased by 30% per additional enemy, up to 150%. (2 Min Cooldown)\nSell Price:" }
entries[249340] = { ["name"] = "Wraps of Cosmic Madness", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\nUse: Desperately unravel yourself over 2 sec to unleash a barrage of 10 cosmic missiles at your target, increased by your haste. Each deals ( 225 * 1 ) Cosmic damage split between nearby enemies. Damage increased by 30% per additional enemy, up to 150%.\n\nAllied deaths induce further madness, reducing the cooldown by 60 sec. (2 Min Cooldown)\n\"Is it mad to sacrifice your world for victory?\"\nSell Price:" }
entries[249341] = { ["name"] = "Volatile Void Suffuser", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 13 Haste\nEquip: Your healing spells and abilities have a high chance to grant you Void Suffusion for 12 sec, increasing your Intellect by 15 plus an additional ( 15 / 100) Intellect for every 1% health the target was missing. Multiple Suffusions may overlap.\nSell Price:" }
entries[249342] = { ["name"] = "Heart of Ancient Hunger", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Strength\nEquip: Your attacks have a chance to increase your Critical Strike by 83 and size, diminishing over 12 sec.\nSell Price:" }
entries[249343] = { ["name"] = "Gaze of the Alnseer", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 13 Mastery\nEquip: Your damage and healing has a chance to grant you Alnsight for 12 sec. While active, casting spells and abilities manifests unstable Alnscorned and consumes their essence to grant you 3 Primary Stat for 12 sec. Multiple applications may overlap.\n\"There are some places the faithful dare not look.\"\nSell Price:" }
entries[249344] = { ["name"] = "Light Company Guidon", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 [Agility or Strength]\nEquip: You are a volunteer of the Vanguard of the Light.\nUse: Lead the charge to gain 74 Haste for 15 sec. All Vanguard of the Light volunteers within 40 yards also gain 19 Speed for 6 sec. (1 Min, 30 Sec Cooldown)\n\"Forward, the Vanguard of the Light!\"\nSell Price:" }
entries[249345] = { ["name"] = "Ranger-Captain's Iridescent Insignia", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Agility\nUse: Unleash a Silverstrike Trick Shot, critically striking your target and a nearby enemy for ( 1208 * 1 ) Arcane damage. This damage is further increased by your critical strike chance.\n\nYour critical strikes have a high chance to reduce this cooldown by 5 sec. (3 Min Cooldown)\nSell Price:" }
entries[249346] = { ["name"] = "Vaelgor's Final Stare", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+9 Intellect\nUse: Seize the eye's draconic power, granting you 149 Mastery diminishing over 15 sec and allowing you to see hidden enemies. (1 Min, 30 Sec Cooldown)\nSell Price:" }
