entries[249386] = { ["name"] = "Ghost Gear", ["text"] = "Cosmetic\nBinds to Warband\nUse: Allows you to see spooky apparitions within the neighborhood. (5 Sec Cooldown)\n\"Gain the ability to see and catch spooky apparitions!\"\nUse: Add this appearance to your Warband collection." }
entries[249387] = { ["name"] = "Latent Shadowgraft", ["text"] = "Quest Item\n\"A metal used by the domanaar to enforce control over others.\"" }
entries[249400] = { ["name"] = "Stack of Chronoqueries", ["text"] = "Binds when picked up\nUnique (3)\nUse: Refresh your Infinite Research assignments and view the new set, if one is available.\nRequires level 10 to 90 ( 90)\n\"So many questions, so little time...\"" }
entries[249401] = { ["name"] = "Vial of Gelatinous Ooze", ["text"] = "Quest Item\n\"A vial containing a thick, gelatinous ooze collected from BOSS 1.\"" }
entries[249402] = { ["name"] = "Hellebora's Thorn", ["text"] = "Quest Item\n\"Harvested from the serrated jaws of the hydra Hellebora, the edge of this thorn is wickedly sharp and difficult to handle.\"" }
entries[249403] = { ["name"] = "Toadshade Petals", ["text"] = "Quest Item\n\"A collection of large olive-green petals, gathered from the hydra Toadshade.\"" }
entries[249404] = { ["name"] = "Choking Vines", ["text"] = "Quest Item\n\"This coil of thick vines harvested from Muckmire writhes in your grasp, attempting to squeeze whatever it can.\"" }
entries[249405] = { ["name"] = "Luminescent Stalks", ["text"] = "Quest Item\n\"Long rubbery stalks with a bioluminescent orb at their apex.\"" }
entries[249406] = { ["name"] = "Gorebarb's Pincers", ["text"] = "Quest Item\n\"A set of sharp, curving pincers, harvested from Gorebarb.\"" }
entries[249407] = { ["name"] = "Harvested Lightwood", ["text"] = "Quest Item\n\"The cut wood feels comfortably warm to the touch and seems to emit the faintest glow from the inside grain.\"" }
entries[249408] = { ["name"] = "Thorntusks of Dionaea", ["text"] = "Quest Item\n\"A set of wickedly sharp tusks, harvested from the thornmaw Dionaea.\"" }
entries[249411] = { ["name"] = "Twilight Tokens", ["text"] = "Quest Item\n\"The Twilight Hammer has no further use for this.\"" }
entries[249412] = { ["name"] = "Smelly Left Shoe", ["text"] = "Quest Item\n\"We could look into weaponizing this stench.\"" }
entries[249413] = { ["name"] = "Previously-Loved Earring", ["text"] = "Quest Item\n\"There's barely any ear still attached.\"" }
entries[249414] = { ["name"] = "Feelings Journal", ["text"] = "Quest Item\n\"Some days, me do not think leader appreciate how big me stomp or how hard me smash. Why me bother?\"" }
entries[249415] = { ["name"] = "Throk's Scroll of Doom", ["text"] = "Quest Item\n\"Almost as doom-filled as Borvin's Scroll of Doom.\"" }
entries[249416] = { ["name"] = "Partially-Eaten Rations", ["text"] = "Quest Item\n\"You can just brush the bugs off, if you're really hungry.\"" }
entries[249417] = { ["name"] = "Flamethrower", ["text"] = "Quest Item\nUse: The broker's fire burns simultaneously in multiple energy spectrums. (10 Sec Cooldown)\n\"Sometimes, fire is the answer.\"" }
entries[249418] = { ["name"] = "Lightblooming Bulb", ["text"] = "Quest Item\n\"Deceptively gentle glowing bulb. The botanist's test of nature versus nurture.\"" }
entries[249421] = { ["name"] = "Mana-Fortified Vintage", ["text"] = "Quest Item\n\"An extremely expensive reserve bottled during the early years of Anasterian's reign.\"" }
entries[249422] = { ["name"] = "Sunsilk", ["text"] = "Quest Item\n\"Used to create exquisite silk threads, with just a hint of warmth.\"" }
